1	package copilotcli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10	
11		"github.com/entireio/cli/cmd/entire/cli/agent"
12		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15	)
16	
17	// HooksFileName is the hooks file managed by Entire for Copilot CLI.
18	const HooksFileName = "entire.json"
19	
20	// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
21	const hooksDir = ".github/hooks"
22	
23	// entireHookPrefixes are command prefixes that identify Entire hooks in the
24	// bash field. The "go run" prefix is retained so hooks installed by older
25	// versions are still recognized.
26	var entireHookPrefixes = []string{
27		"entire ",
28		agent.LocalDevHookScript + " ",
29		`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
30	}
31	
32	// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
33	var hookConfigKey = map[string]string{
34		HookNameUserPromptSubmitted: "userPromptSubmitted",
35		HookNameSessionStart:        "sessionStart",
36		HookNameAgentStop:           "agentStop",
37		HookNameSessionEnd:          "sessionEnd",
38		HookNameSubagentStop:        "subagentStop",
39		HookNamePreToolUse:          "preToolUse",
40		HookNamePostToolUse:         "postToolUse",
41		HookNameErrorOccurred:       "errorOccurred",
42	}
43	
44	// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json and the
45	// VS Code-native hook file .github/hooks/entire-vscode.json (see vscode_hooks.go).
46	// If force is true, removes existing Entire hooks before installing.
47	// Returns the number of Copilot CLI hooks installed.
48	// Unknown top-level fields and hook types are preserved on round-trip.
49	func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
50		worktreeRoot, err := paths.WorktreeRoot(ctx)
51		if err != nil {
52			worktreeRoot = "."
53		}
54	
55		// Install the VS Code-native hook file alongside the Copilot CLI file so
56		// Copilot sessions run from VS Code's agent hooks (Preview) are captured.
57		if err := c.installVSCodeHooks(worktreeRoot, localDev, force); err != nil {
58			return 0, err
59		}
60	
61		hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
62	
63		// Use raw maps to preserve unknown fields on round-trip
64		var rawFile map[string]json.RawMessage
65		var rawHooks map[string]json.RawMessage
66	
67		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
68		switch {
69		case readErr == nil:
70			if err := json.Unmarshal(existingData, &rawFile); err != nil {
71				return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
72			}
73			if hooksRaw, ok := rawFile["hooks"]; ok {
74				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
75					return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
76				}
77			}
78			if _, ok := rawFile["version"]; !ok {
79				rawFile["version"] = json.RawMessage(`1`)
80			}
81		case errors.Is(readErr, os.ErrNotExist):
82			rawFile = map[string]json.RawMessage{
83				"version": json.RawMessage(`1`),
84			}
85		default:
86			return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
87		}
88	
89		if rawHooks == nil {
90			rawHooks = make(map[string]json.RawMessage)
91		}
92	
93		// Parse existing entries for each hook type we manage
94		hookEntries := make(map[string][]CopilotHookEntry)
95		for _, hookName := range c.HookNames() {
96			key := hookConfigKey[hookName]
97			var entries []CopilotHookEntry
98			if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
99				return 0, fmt.Errorf("failed to parse %s hooks: %w", key, err)
100			}
101			hookEntries[hookName] = entries
102		}
103	
104		// If force, remove existing Entire hooks first
105		if force {
106			for hookName, entries := range hookEntries {
107				hookEntries[hookName] = removeEntireHooks(entries)
108			}
109		}
110	
111		// Define command prefix
112		var cmdPrefix string
113		if localDev {
114			cmdPrefix = agent.LocalDevHookScript + " hooks copilot-cli "
115		} else {
116			cmdPrefix = "entire hooks copilot-cli "
117		}
118	
119		count := 0
120	
121		// Add hooks that don't already exist
122		for _, hookName := range c.HookNames() {
123			cmd := cmdPrefix + hookName
124			if !localDev {
125				cmd = agent.WrapProductionSilentHookCommand(cmd)
126			}
127			entries := hookEntries[hookName]
128			if !hookBashExists(entries, cmd) {
129				entries = append(entries, CopilotHookEntry{
130					Type:    "command",
131					Bash:    cmd,
132					Comment: "Entire CLI",
133				})
134				hookEntries[hookName] = entries
135				count++
136			}
137		}
138	
139		if count == 0 {
140			return 0, nil
141		}
142	
143		// Marshal modified hook types back into rawHooks
144		for _, hookName := range c.HookNames() {
145			key := hookConfigKey[hookName]
146			if err := marshalCopilotHookType(rawHooks, key, hookEntries[hookName]); err != nil {
147				return 0, fmt.Errorf("failed to marshal %s hooks: %w", key, err)
148			}
149		}
150	
151		// Marshal hooks and update raw file
152		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
153		if err != nil {
154			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
155		}
156		rawFile["hooks"] = hooksJSON
157	
158		// Write to file
159		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
160			return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
161		}
162	
163		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
164		if err != nil {
165			return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
166		}
167	
168		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
169			return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
170		}
171	
172		return count, nil
173	}
174	
175	// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
176	// Unknown top-level fields and hook types are preserved on round-trip.
177	func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
178		worktreeRoot, err := paths.WorktreeRoot(ctx)
179		if err != nil {
180			worktreeRoot = "."
181		}
182	
183		// Remove the VS Code-native hook file's Entire entries too.
184		if err := c.uninstallVSCodeHooks(worktreeRoot); err != nil {
185			return err
186		}
187	
188		hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
189		data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
190		if err != nil {
191			if errors.Is(err, os.ErrNotExist) {
192				return nil // No hooks file means nothing to uninstall
193			}
194			return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
195		}
196	
197		var rawFile map[string]json.RawMessage
198		if err := json.Unmarshal(data, &rawFile); err != nil {
199			return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
200		}
201	
202		var rawHooks map[string]json.RawMessage
203		if hooksRaw, ok := rawFile["hooks"]; ok {
204			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
205				return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
206			}
207		}
208		if rawHooks == nil {
209			rawHooks = make(map[string]json.RawMessage)
210		}
211	
212		// Parse and remove Entire hooks from each hook type we manage
213		for _, hookName := range c.HookNames() {
214			key := hookConfigKey[hookName]
215			var entries []CopilotHookEntry
216			if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
217				return fmt.Errorf("failed to parse %s hooks: %w", key, err)
218			}
219			entries = removeEntireHooks(entries)
220			if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
221				return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
222			}
223		}
224	
225		// Marshal hooks back (preserving unknown hook types)
226		if len(rawHooks) > 0 {
227			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
228			if err != nil {
229				return fmt.Errorf("failed to marshal hooks: %w", err)
230			}
231			rawFile["hooks"] = hooksJSON
232		} else {
233			delete(rawFile, "hooks")
234		}
235	
236		// Write back
237		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
238		if err != nil {
239			return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
240		}
241	
242		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
243			return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
244		}
245		return nil
246	}
247	
248	// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
249	func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
250		worktreeRoot, err := paths.WorktreeRoot(ctx)
251		if err != nil {
252			worktreeRoot = "."
253		}
254		hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
255		data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
256		if err != nil {
257			if !errors.Is(err, os.ErrNotExist) {
258				logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
259			}
260			// The Copilot CLI file may be absent while the VS Code file is present.
261			return c.areVSCodeHooksInstalled(worktreeRoot)
262		}
263	
264		var hooksFile CopilotHooksFile
265		if err := json.Unmarshal(data, &hooksFile); err != nil {
266			logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
267			return c.areVSCodeHooksInstalled(worktreeRoot)
268		}
269	
270		return c.areVSCodeHooksInstalled(worktreeRoot) ||
271			hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
272			hasEntireHook(hooksFile.Hooks.SessionStart) ||
273			hasEntireHook(hooksFile.Hooks.AgentStop) ||
274			hasEntireHook(hooksFile.Hooks.SessionEnd) ||
275			hasEntireHook(hooksFile.Hooks.SubagentStop) ||
276			hasEntireHook(hooksFile.Hooks.PreToolUse) ||
277			hasEntireHook(hooksFile.Hooks.PostToolUse) ||
278			hasEntireHook(hooksFile.Hooks.ErrorOccurred)
279	}
280	
281	// GetSupportedHooks returns the normalized lifecycle events this agent supports.
282	// Note: HookNames() returns 8 hooks but GetSupportedHooks() returns only 6.
283	// The two not listed here are:
284	//   - subagentStop: handled by ParseHookEvent (returns SubagentEnd), but there is no
285	//     HookType constant for subagent events (they use EventType instead).
286	//   - errorOccurred: pass-through hook with no lifecycle action (ParseHookEvent returns nil).
287	func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
288		return []agent.HookType{
289			agent.HookSessionStart,
290			agent.HookSessionEnd,
291			agent.HookUserPromptSubmit,
292			agent.HookStop,
293			agent.HookPreToolUse,
294			agent.HookPostToolUse,
295		}
296	}
297	
298	// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
299	func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) error {
300		if data, ok := rawHooks[hookType]; ok {
301			if err := json.Unmarshal(data, target); err != nil {
302				return fmt.Errorf("invalid JSON for hook type %s: %w", hookType, err)
303			}
304		}
305		return nil
306	}
307	
308	// marshalCopilotHookType marshals a hook type back into rawHooks.
309	// If the slice is empty, removes the key from rawHooks.
310	func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) error {
311		if len(entries) == 0 {
312			delete(rawHooks, hookType)
313			return nil
314		}
315		data, err := jsonutil.MarshalWithNoHTMLEscape(entries)
316		if err != nil {
317			return fmt.Errorf("failed to marshal hook type %s: %w", hookType, err)
318		}
319		rawHooks[hookType] = data
320		return nil
321	}
322	
323	// hookBashExists checks if a hook with the given bash command already exists.
324	func hookBashExists(entries []CopilotHookEntry, bash string) bool {
325		for _, entry := range entries {
326			if entry.Bash == bash {
327				return true
328			}
329		}
330		return false
331	}
332	
333	// isEntireHook checks if a hook entry's bash command belongs to Entire.
334	func isEntireHook(bash string) bool {
335		return agent.IsManagedHookCommand(bash, entireHookPrefixes)
336	}
337	
338	// hasEntireHook checks if any entry in the slice is an Entire hook.
339	func hasEntireHook(entries []CopilotHookEntry) bool {
340		for _, entry := range entries {
341			if isEntireHook(entry.Bash) {
342				return true
343			}
344		}
345		return false
346	}
347	
348	// removeEntireHooks removes all Entire hooks from the slice.
349	func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
350		result := make([]CopilotHookEntry, 0, len(entries))
351		for _, entry := range entries {
352			if !isEntireHook(entry.Bash) {
353				result = append(result, entry)
354			}
355		}
356		return result
357	}
